#include "rsr_private.h"
#include "status.h"
#include "cmd.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
 
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void rsr_state_start_on(void)
{
  #define CMD_INSERT (cmd_q_insert (INPUT_RS_STARTER, RSR_CMD_INSERT_TIMEOUT) && cmd_q_insert (INPUT_RS_ACCESSORY | INPUT_ON, RSR_CMD_INSERT_TIMEOUT))
  
  if((RSR_CRANK_RELEASE || (rsr_vars.running.ms + rsr_vars.running.sec * 1000) >= rsr_opt.crank_time) && CMD_INSERT)
    {
      #if RSR_STARTER_ENA == 1
	    ;
	  #endif
	  #if RSR_ACC_ENA == 1
        RSR_ACC_SET ;
	  #endif

      rsr_set_state   (RSR_STATE_RUN) ;

	  if(RSR_CRANK_RELEASE || TACHLESS)
	    {
      	  rsr_notify_start(TRUE) ;
      	  rsr_parking_pattern (RSR_PRK_CONSTANT) ;
	    }   
    }     
}


